/** The web's stylesheet for a visualization's page. */
export const stylesheet = "/*\n * The stylesheet of an inline visualization (Viz.tsx): an HTML file placed in a message, drawn in a sandboxed frame.\n * Two layers, after Codex's Visualize: the page hands in ember's own tokens as --e-* (its palette, type, corners, for\n * the theme it shows), and what an agent writes against is the contract below — the variable and class names of\n * Codex's visualize.css, so an agent that knows one knows the other. Keep it in step with skills/ember-viz.md.\n */\n:root {\n\n  /* Agent-facing contract. */\n  --background: var(--e-canvas, #fff);\n  --foreground: var(--e-text, #3a3d42);\n  --card: var(--e-paper, #f6f4ef);\n  --card-foreground: var(--foreground);\n  --popover: var(--e-canvas, #fff);\n  --popover-foreground: var(--foreground);\n  --primary: var(--e-primary, #24272b);\n  --primary-foreground: var(--e-on-primary, #fff);\n  --secondary: var(--e-neutral-bg, #f0f1f3);\n  --secondary-foreground: var(--foreground);\n  --muted: var(--e-neutral-bg, #f0f1f3);\n  --muted-foreground: var(--e-muted, #6b7079);\n  --accent: var(--e-accent-bg, #fdf0ea);\n  --accent-foreground: var(--e-accent-text, #a8491f);\n  --brand: var(--e-accent, #e8763f);\n  --destructive: var(--e-red, #b53a2c);\n  --border: var(--e-line, #e8e6e1);\n  --border-strong: var(--e-line-strong, #cdd0d5);\n  --input: var(--e-line-strong, #cdd0d5);\n  --ring: var(--e-field-focus, #646970);\n  --hover: var(--e-hover, #f1efeb);\n  --selected: var(--e-selected, #ebe8e2);\n  --shadow: var(--e-shadow, rgb(0 0 0 / 10%));\n\n  --blue: var(--e-blue, #2b5fc4);\n  --green: var(--e-green, #1d7a55);\n  --orange: var(--e-accent, #e8763f);\n  --red: var(--e-red, #b53a2c);\n  --purple: var(--e-code-inline, #7c3fa0);\n  --yellow: var(--e-amber, #8a6414);\n  --blue-bg: var(--e-blue-bg, #eef3fc);\n  --green-bg: var(--e-green-bg, #ecf7f1);\n  --orange-bg: var(--e-accent-bg, #fdf0ea);\n  --red-bg: var(--e-red-bg, #fcefed);\n  --yellow-bg: var(--e-amber-bg, #fcf5e6);\n  /* still.fail has no purple ground of its own: its purple tinted into the page's, so it follows the theme. */\n  --purple-bg: color-mix(in srgb, var(--purple) 12%, var(--background));\n  /* Series colours in order, for charts: tell series apart by label or shape too, never by colour alone. */\n  --chart-1: var(--blue);\n  --chart-2: var(--orange);\n  --chart-3: var(--green);\n  --chart-4: var(--purple);\n  --chart-5: var(--yellow);\n  --chart-6: var(--red);\n\n  --font-sans: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\", \"Hiragino Sans GB\", sans-serif;\n  --font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;\n  --font-size-base: 14px;\n  --font-size-small: 12px;\n  --font-size-h1: 22px;\n  --font-size-h2: 18px;\n  --font-size-h3: 16px;\n  --line-height: 1.6;\n  --radius-card: var(--e-r-card, 20px);\n  --radius-field: var(--e-r-field, 12px);\n  --radius-small: calc(var(--radius-field) / 2);\n  --corner-shape: var(--e-corner-shape, round);\n  --dur: 140ms;\n  --ease-out: cubic-bezier(.2, .7, .2, 1);\n\n  background: transparent;\n  color: var(--foreground);\n  font: var(--font-size-base) / var(--line-height) var(--font-sans);\n  -webkit-font-smoothing: antialiased;\n}\n\n*, *::before, *::after { box-sizing: border-box; }\nhtml, body { margin: 0; padding: 0; }\n/* The frame is as tall as the content (Viz.tsx), so it never scrolls: a fractional scale on Windows can leave the\n   content a pixel over, enough for a scrollbar the width of the frame (2026-10-14). */\nhtml { overflow: hidden; }\n[hidden] { display: none !important; }\nbody { padding: 2px; overflow-wrap: anywhere; }\nh1, h2, h3, h4 { margin: 0 0 .5em; line-height: 1.3; font-weight: 600; }\nh1 { font-size: var(--font-size-h1); }\nh2 { font-size: var(--font-size-h2); }\nh3 { font-size: var(--font-size-h3); }\nh4 { font-size: var(--font-size-base); }\np { margin: 0 0 .75em; }\np:last-child { margin-bottom: 0; }\na { color: var(--blue); text-decoration: none; }\na:hover { text-decoration: underline; }\ncode, kbd, pre { font-family: var(--font-mono); font-size: .92em; }\ncode { padding: .1em .35em; border-radius: var(--radius-small); background: var(--muted); }\npre { margin: 0 0 .75em; padding: 10px 12px; border-radius: var(--radius-field); background: var(--muted); overflow-x: auto; }\npre code { padding: 0; background: none; }\nhr { height: 1px; margin: 12px 0; border: 0; background: var(--border); }\nsvg { color: var(--foreground); }\nsvg text { fill: currentColor; font-family: var(--font-sans); }\n\n/* Text. */\n.text-muted { color: var(--muted-foreground); }\n.text-small { font-size: var(--font-size-small); }\n.text-destructive { color: var(--destructive); }\n.text-warning { color: var(--yellow); }\n.text-success { color: var(--green); }\n.text-brand { color: var(--accent-foreground); }\n.tabular-nums { font-variant-numeric: tabular-nums; }\n.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n.cursor-interaction { cursor: pointer; }\n\n/* Surfaces. */\n.card {\n  padding: 16px; border: 1px solid var(--border); border-radius: var(--radius-card); corner-shape: var(--corner-shape);\n  background: var(--card); color: var(--card-foreground);\n}\n.card > :last-child { margin-bottom: 0; }\n.widget { display: flex; flex-direction: column; gap: 12px; }\n.viz-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; }\n.viz-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }\n.viz-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; }\n.viz-dotted-background {\n  background-image: radial-gradient(color-mix(in srgb, var(--foreground) 14%, transparent) 1px, transparent 1px);\n  background-size: 14px 14px;\n}\n\n/* A figure: a number with its label. */\n.viz-stat { display: flex; flex-direction: column; gap: 2px; }\n.viz-stat-label { color: var(--muted-foreground); font-size: var(--font-size-small); }\n.viz-stat-value { font-size: 24px; font-weight: 600; line-height: 1.2; font-variant-numeric: tabular-nums; }\n\n/* Badges: neutral by default, a status colour when named. */\n.viz-badge {\n  display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 8px; border-radius: 999px;\n  background: var(--muted); color: var(--foreground); font-size: var(--font-size-small); font-weight: 500; white-space: nowrap;\n}\n.viz-badge.is-blue { background: var(--blue-bg); color: var(--blue); }\n.viz-badge.is-green { background: var(--green-bg); color: var(--green); }\n.viz-badge.is-orange { background: var(--orange-bg); color: var(--accent-foreground); }\n.viz-badge.is-red { background: var(--red-bg); color: var(--red); }\n.viz-badge.is-yellow { background: var(--yellow-bg); color: var(--yellow); }\n.viz-badge.is-purple { background: var(--purple-bg); color: var(--purple); }\n\n/* Diagrams (ember's own): boxes in a flow, arrows between them, a note aside. */\n.viz-flow { display: flex; flex-wrap: wrap; align-items: stretch; gap: 8px; }\n.viz-flow.is-vertical { flex-direction: column; align-items: flex-start; }\n.viz-node {\n  display: flex; flex-direction: column; gap: 2px; min-width: 96px; padding: 10px 12px;\n  border: 1px solid var(--border-strong); border-radius: var(--radius-field); corner-shape: var(--corner-shape);\n  background: var(--background);\n}\n.viz-node-title { font-weight: 600; }\n.viz-node-body { color: var(--muted-foreground); font-size: var(--font-size-small); }\n.viz-node.is-active { border-color: var(--brand); background: var(--accent); }\n.viz-node.is-blue { border-color: color-mix(in srgb, var(--blue) 40%, transparent); background: var(--blue-bg); }\n.viz-node.is-green { border-color: color-mix(in srgb, var(--green) 40%, transparent); background: var(--green-bg); }\n.viz-node.is-red { border-color: color-mix(in srgb, var(--red) 40%, transparent); background: var(--red-bg); }\n.viz-node.is-yellow { border-color: color-mix(in srgb, var(--yellow) 40%, transparent); background: var(--yellow-bg); }\n.viz-node.is-purple { border-color: color-mix(in srgb, var(--purple) 40%, transparent); background: var(--purple-bg); }\n.viz-arrow {\n  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; min-width: 40px;\n  color: var(--muted-foreground); font-size: var(--font-size-small); text-align: center;\n}\n.viz-arrow::after { content: \"→\"; font-size: 16px; line-height: 1; }\n.viz-flow.is-vertical .viz-arrow::after { content: \"↓\"; }\n.viz-note {\n  padding: 8px 12px; border-left: 3px solid var(--brand); border-radius: var(--radius-small);\n  background: var(--accent); color: var(--foreground); font-size: var(--font-size-small);\n}\n\n/* Buttons. */\n.btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; padding: 0 12px;\n  border: 1px solid var(--border-strong); border-radius: var(--radius-field); corner-shape: var(--corner-shape);\n  background: var(--background); color: var(--foreground); font: inherit; font-weight: 500; white-space: nowrap;\n  cursor: pointer; transition: background var(--dur) var(--ease-out), border-color var(--dur) var(--ease-out);\n}\n.btn:hover { background: var(--hover); }\n.btn:disabled { opacity: .5; cursor: default; }\n.btn-primary { border-color: var(--primary); background: var(--primary); color: var(--primary-foreground); }\n.btn-primary:hover { border-color: var(--e-primary-hover, var(--primary)); background: var(--e-primary-hover, var(--primary)); }\n.btn-ghost { border-color: transparent; background: transparent; }\n.btn-ghost:hover { background: var(--hover); }\n.btn.is-selected { border-color: var(--brand); background: var(--accent); color: var(--accent-foreground); }\n.btn-sm { height: 26px; padding: 0 8px; font-size: var(--font-size-small); }\n\n/* Forms. */\n.form-label { display: block; margin-bottom: 4px; color: var(--muted-foreground); font-size: var(--font-size-small); }\n.form-control, .form-select {\n  width: 100%; height: 34px; padding: 0 10px; border: 1px solid var(--input); border-radius: var(--radius-field);\n  corner-shape: var(--corner-shape); background: var(--background); color: var(--foreground); font: inherit;\n}\ntextarea.form-control { height: auto; min-height: 72px; padding: 8px 10px; resize: vertical; }\n.form-control:hover, .form-select:hover { border-color: var(--e-field-hover, var(--input)); }\n.form-control:focus, .form-select:focus { border-color: var(--ring); outline: none; }\n.form-check { display: inline-flex; align-items: center; gap: 6px; cursor: pointer; }\n.form-check-input { width: 16px; height: 16px; margin: 0; accent-color: var(--brand); }\n.form-check-label { cursor: pointer; }\n.form-switch .form-check-input { width: 28px; }\n.form-range { width: 100%; accent-color: var(--brand); }\n.form-control-color { width: 34px; height: 34px; padding: 2px; border: 1px solid var(--input); border-radius: var(--radius-small); background: none; }\n\n/* Tabs as pills. */\n.nav { display: flex; flex-wrap: wrap; gap: 4px; margin: 0; padding: 0; list-style: none; }\n.nav-justified > * { flex: 1; }\n.nav-link {\n  display: inline-flex; align-items: center; justify-content: center; height: 30px; padding: 0 12px; border: 0;\n  border-radius: 999px; background: none; color: var(--muted-foreground); font: inherit; cursor: pointer;\n}\n.nav-link:hover { background: var(--hover); color: var(--foreground); text-decoration: none; }\n.nav-pills .nav-link.is-selected, .nav-pills .nav-link.active { background: var(--primary); color: var(--primary-foreground); }\n\n/* Tables. */\n.table-responsive { max-width: 100%; overflow-x: auto; }\n.table { width: 100%; border-collapse: collapse; font-size: var(--font-size-base); }\n.table th, .table td { padding: 7px 10px; border-bottom: 1px solid var(--border); text-align: left; vertical-align: top; }\n.table th { color: var(--muted-foreground); font-size: var(--font-size-small); font-weight: 500; }\n.table tr:last-child td { border-bottom: 0; }\n.table td.num, .table th.num { text-align: right; font-variant-numeric: tabular-nums; }\n\n/* Progress. */\n.progress { height: 8px; overflow: hidden; border-radius: 999px; background: var(--muted); }\n.progress-bar { height: 100%; border-radius: inherit; background: var(--brand); transition: width var(--dur) var(--ease-out); }\n\n/* The tooltip the frame draws for any element with data-tooltip (see bridge.js). */\n.viz-tooltip {\n  position: fixed; z-index: 10; max-width: 240px; padding: 5px 8px; border-radius: var(--radius-small);\n  background: var(--primary); color: var(--primary-foreground); font-size: var(--font-size-small); line-height: 1.4;\n  white-space: pre-line; pointer-events: none;\n}\n";
/** The web's bridge, run first in a visualization's page. */
export const bridge = "// Runs first inside an inline visualization's frame (Viz.tsx). The frame is sandboxed without its page's origin, so\n// the two only talk by messages: the frame says how tall its content is, the page says when its theme changes (the\n// --e-* tokens ember-viz.css maps), and the frame draws the tooltip of any element with data-tooltip.\n//\n// The widget's API is window.ember, named as Codex's Visualize names window.openai (which it also answers to, for a\n// widget written for that): widgetState and setWidgetState keep what the widget wants back when it is shown again,\n// sendFollowUpMessage puts words in the chat's composer for the person to send — only on their click or key.\n(() => {\n  const root = document.documentElement;\n  // The page is the parent in a message; opened beside the chat it is the top, over the preview's own frame\n  // (Preview.tsx), which takes no notice.\n  const pages = parent === top ? [parent] : [parent, top];\n  const post = (message) => { for (const page of pages) page.postMessage({ emberViz: true, ...message }, \"*\"); };\n\n  const given = document.getElementById(\"ember-viz-state\");\n  let state = JSON.parse(given?.textContent || \"{}\").widgetState ?? null;\n  given?.remove();\n  const api = {\n    get widgetState() { return state; },\n    setWidgetState(next) {\n      const json = JSON.stringify(next ?? null);\n      if (json.length > 16 * 1024) return Promise.reject(new Error(\"widgetState is over 16 KiB\"));\n      state = JSON.parse(json);\n      post({ type: \"state\", state });\n      return Promise.resolve();\n    },\n    sendFollowUpMessage({ prompt } = {}) {\n      if (typeof prompt !== \"string\" || !prompt.trim()) return Promise.reject(new Error(\"sendFollowUpMessage needs a prompt\"));\n      // Only as the person acts: a widget cannot write to the chat by itself.\n      if (navigator.userActivation && !navigator.userActivation.isActive) return Promise.reject(new Error(\"sendFollowUpMessage needs a click or key press\"));\n      post({ type: \"followup\", prompt });\n      return Promise.resolve();\n    },\n  };\n  Object.defineProperty(window, \"ember\", { value: api });\n  Object.defineProperty(window, \"openai\", { value: api });\n\n  let last = 0;\n  const sendHeight = () => {\n    const height = Math.ceil(Math.max(document.body?.scrollHeight ?? 0, document.body?.getBoundingClientRect().height ?? 0));\n    if (height !== last) {\n      last = height;\n      post({ type: \"height\", height });\n    }\n  };\n  addEventListener(\"message\", (event) => {\n    if (!pages.includes(event.source) || !event.data?.emberViz) return;\n    if (event.data.type === \"theme\") {\n      for (const [name, value] of Object.entries(event.data.tokens ?? {})) root.style.setProperty(name, value);\n      root.dataset.theme = event.data.scheme;\n      root.style.colorScheme = event.data.scheme;\n      // For charts drawn with resolved colours (a canvas, a chart library): redraw on this.\n      dispatchEvent(new CustomEvent(\"ember-viz:theme\", { detail: { scheme: event.data.scheme } }));\n    }\n  });\n\n  let tip = null;\n  const place = (target) => {\n    const r = target.getBoundingClientRect();\n    const t = tip.getBoundingClientRect();\n    const left = Math.min(Math.max(4, r.left + r.width / 2 - t.width / 2), innerWidth - t.width - 4);\n    const top = r.top - t.height - 6 >= 0 ? r.top - t.height - 6 : r.bottom + 6;\n    tip.style.left = `${left}px`;\n    tip.style.top = `${top}px`;\n  };\n  const show = (target) => {\n    const text = target.getAttribute(\"data-tooltip\");\n    if (!text) return hide();\n    tip ??= Object.assign(document.createElement(\"div\"), { className: \"viz-tooltip\", role: \"tooltip\" });\n    tip.textContent = text;\n    document.body.append(tip);\n    place(target);\n  };\n  const hide = () => tip?.remove();\n  addEventListener(\"pointerover\", (e) => { const t = e.target.closest?.(\"[data-tooltip]\"); t ? show(t) : hide(); });\n  addEventListener(\"focusin\", (e) => { const t = e.target.closest?.(\"[data-tooltip]\"); t ? show(t) : hide(); });\n  addEventListener(\"pointerleave\", hide);\n  addEventListener(\"scroll\", hide, true);\n\n  addEventListener(\"DOMContentLoaded\", () => {\n    sendHeight();\n    new ResizeObserver(sendHeight).observe(document.body);\n  });\n  addEventListener(\"load\", sendHeight);\n  addEventListener(\"error\", (e) => post({ type: \"error\", message: String(e.message ?? e) }));\n})();\n";
